select budget_bucket, stddev_budget, avg_budget from (select case when budget >= 3822000 then 'high' when budget >= 2056000 then 'mid' else 'low' end as budget_bucket, round(stddev(budget), 2) as stddev_budget, round(avg(budget), 2) as avg_budget from departments group by case when budget >= 3822000 then 'high' when budget >= 2056000 then 'mid' else 'low' end) as agg where stddev_budget >= 42 order by avg_budget desc, budget_bucket limit 50;
